:root {
  color-scheme: light;
  --ink: #282b43;
  --paper: #fffaf0;
  --coral: #e97960;
  --teal: #4f9d91;
  --gold: #f1bf5b;
}
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; background-color: #f4e9d3; background-image: radial-gradient(#dfcfb1 1.5px, transparent 1.5px); background-size: 18px 18px; color: var(--ink); font: 16px/1.5 system-ui, sans-serif; }
.page { width: min(100% - 32px, 420px); margin: 0 auto; padding: 38px 0 32px; text-align: center; }
.eyebrow { margin: 0 0 14px; font-size: 16px; font-weight: 800; letter-spacing: .14em; }
.card { overflow: hidden; border: 4px solid var(--ink); background: var(--paper); text-align: left; box-shadow: 8px 8px 0 var(--ink); }
.card-top, .card-bottom { display: flex; align-items: center; justify-content: space-between; min-height: 48px; padding: 0 18px; background: var(--ink); color: var(--paper); font-size: 16px; font-weight: 800; letter-spacing: .08em; }
.pixel-mark { color: var(--gold); font-size: 22px; }.status-dot { width: 12px; height: 12px; background: var(--teal); box-shadow: 0 0 0 3px var(--paper); }
.portrait { position: relative; height: 188px; overflow: hidden; background: var(--teal); image-rendering: pixelated; }
.sun { position: absolute; top: 24px; left: calc(50% - 57px); width: 114px; height: 114px; background: var(--gold); }
.hair { position: absolute; top: 53px; left: calc(50% - 42px); width: 84px; height: 70px; background: var(--ink); box-shadow: -12px 10px 0 var(--ink), 12px 6px 0 var(--ink), 0 -11px 0 var(--ink); }
.face { position: absolute; top: 70px; left: calc(50% - 30px); width: 60px; height: 58px; background: #f2a789; box-shadow: -8px 12px 0 #f2a789, 8px 12px 0 #f2a789; }
.face::before { content: "▪"; position: absolute; top: 18px; left: 10px; color: var(--ink); font-size: 18px; text-shadow: 26px 0 var(--ink); }
.face::after { content: ""; position: absolute; bottom: 12px; left: 23px; width: 14px; height: 4px; background: var(--coral); }
.shirt { position: absolute; bottom: -29px; left: calc(50% - 57px); width: 114px; height: 68px; background: var(--coral); box-shadow: -14px 10px 0 var(--coral), 14px 10px 0 var(--coral); }
.spark { position: absolute; color: var(--paper); font-size: 28px; }.spark-one { top: 36px; right: 48px; }.spark-two { bottom: 25px; left: 42px; font-size: 42px; }
.profile-copy { padding: 20px 22px 22px; }.field-label { display: flex; justify-content: space-between; margin: 0 0 5px; color: var(--teal); font-size: 16px; font-weight: 800; letter-spacing: .09em; }
h1 { margin: 0; font-size: clamp(27px, 8vw, 34px); line-height: 1.2; }.title-label { margin-top: 18px; }.title { margin: 0; font-size: 19px; font-weight: 700; }.bio-label { margin-top: 18px; }.count { color: var(--ink); font-size: 14px; letter-spacing: 0; font-weight: 600; }.bio { min-height: 72px; margin: 0; line-height: 1.55; }
.editable { border-radius: 2px; outline: 2px dashed transparent; outline-offset: 3px; cursor: text; overflow-wrap: anywhere; }.editable:hover { background: #f1bf5b22; }.editable:focus { outline-color: var(--coral); background: #f1bf5b22; }.editable:empty::before { content: "Click to add text…"; color: #77798a; }
.card-bottom { min-height: 42px; font-size: 14px; }.heart { color: var(--coral); font-size: 20px; }
.actions { display: flex; gap: 12px; margin-top: 24px; }.button { flex: 1; min-height: 50px; border: 3px solid var(--ink); padding: 8px 12px; color: var(--ink); font: inherit; font-weight: 800; cursor: pointer; box-shadow: 4px 4px 0 var(--ink); transition: transform .08s, box-shadow .08s, filter .08s; }.save { background: var(--coral); }.cancel { background: var(--paper); }.button:hover { filter: brightness(1.05); transform: translate(-1px, -1px); box-shadow: 5px 5px 0 var(--ink); }.button:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 var(--ink); }.button:focus-visible { outline: 3px solid var(--teal); outline-offset: 4px; }
.saved { margin: 18px 0 0; color: #286c60; font-weight: 800; }.hint { margin: 24px 0 0; color: #57596c; font-size: 16px; }
[hidden] { display: none !important; }
@media (max-width: 380px) { .page { width: calc(100% - 28px); padding-top: 24px; }.profile-copy { padding-inline: 18px; }.card-top { padding-inline: 14px; } }

const nameField = document.getElementById('profile-name');
const titleField = document.getElementById('profile-title');
const bioField = document.getElementById('profile-bio');
const bioCount = document.getElementById('bio-count');
const savedMessage = document.getElementById('saved-message');
const fields = [nameField, titleField, bioField];
let savedValues = fields.map(field => field.textContent);

function updateBioCount() {
  const length = bioField.textContent.length;
  bioCount.textContent = `${length} / 120`;
  bioCount.setAttribute('aria-label', `${length} of 120 characters`);
}

bioField.addEventListener('input', () => {
  if (bioField.textContent.length > 120) {
    bioField.textContent = bioField.textContent.slice(0, 120);
    const range = document.createRange();
    range.selectNodeContents(bioField);
    range.collapse(false);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
  }
  updateBioCount();
  savedMessage.hidden = true;
});

fields.forEach(field => field.addEventListener('input', () => { savedMessage.hidden = true; }));

document.getElementById('save-button').addEventListener('click', () => {
  savedValues = fields.map(field => field.textContent.trim());
  fields.forEach((field, index) => { field.textContent = savedValues[index]; });
  updateBioCount();
  savedMessage.hidden = false;
});

document.getElementById('cancel-button').addEventListener('click', () => {
  fields.forEach((field, index) => { field.textContent = savedValues[index]; });
  updateBioCount();
  savedMessage.hidden = true;
});

updateBioCount();
